ruleContent.content:
//div[@class="player"]/script/text()
@js:
list=JSON.parse(String(source.getVariable()))
result=String(result)
name=result.match(/mac_url.*?\=/g)[0].replace(/(mac_url.*?)\=/,'$1').trim()   
eval(result)
url="http://api.6uzy.cc/?url="+Array.from(eval(name).split('$$$')[parseInt(list[book.durChapterTitle].i)].split('#')).map(v=>{
	  return v.split('$')
})[parseInt(list[book.durChapterTitle].j)][1]
if(book.durChapterIndex==chapter.index){
		java.startBrowser(url,title)
		java.toast('正在加载视频\n视频加载较慢，请耐心等待')
	}
`<p>【刷新正文】播放<br>或者【点击章节链接】跳转到浏览器播放<br>♡<br>视频地址:<br>${url}</p>`

ruleToc.chapterList:
id.playbox@.play_menu
@js:
list=[]
names={}
bSrc=src
elements=java.getElement('class.play_body')
for(i=0;i<result.length&&i<elements.length;i++){
	  java.setContent(result[i])
	  snamepath='class.play_menu@text'
	  sname=String(java.getString(snamepath))
	         .replace('-------点击展开播放','')
	  java.setContent(elements[i])
	  element=java.getElement('class.play_body@dl@dt')
	  for(j=element.length-1;j>=0;j--){
	  	  java.setContent(element[j])
	  	  name=java.getString('tag.a@text')
	  	  href=java.getString('tag.a@href')
	  	  index=element.length-j-1
	  	  names[`[${sname}]${name}`]={
	  	  	  "i":String(i),
	  	  	  "j":String(index)
	  	  }
	  	  list.push({
	  	  	"name":`[${sname}]${name}`,
	  	  	"href":String(href)
	  	  })
	  }
}
source.setVariable(String(JSON.stringify(names)))
java.setContent(bSrc)
list
